local FishingNetMaker = {}
local PRODUCTS = {
    simple_rope_fishing_net = { name = "Preprosta vrvična ribiška mreža", ropeCost = 3, threadCost = 1, time = 4, cost = 60, food = 15, happiness = 1, description = "Preprosta vrvična ribiška mreža za ribolov." },
    linen_cast_net = { name = "Lanena odmetna mreža", ropeCost = 2, linenCost = 2, threadCost = 1, time = 6, cost = 160, food = 25, happiness = 1, prestige = 2, description = "Lanena odmetna mreža za trgovce." },
    silver_weighted_net = { name = "Srebrnoobtežena mreža", ropeCost = 2, silverCost = 1, linenCost = 2, threadCost = 1, time = 9, cost = 400, food = 38, happiness = 2, prestige = 6, description = "Srebrnoobtežena mreža za plemiče." },
    gold_trimmed_net = { name = "Zlatookrasna mreža", ropeCost = 2, goldCost = 1, silverCost = 1, linenCost = 2, threadCost = 1, time = 13, cost = 950, food = 52, happiness = 3, prestige = 14, description = "Zlatookrasna mreža za visoke plemiče." },
    jewel_set_net = { name = "Draguljasta mreža", ropeCost = 2, goldCost = 1, silverCost = 1, linenCost = 2, threadCost = 1, jewelCost = 1, time = 17, cost = 2100, food = 68, happiness = 5, prestige = 27, description = "Mreža z draguljem za visoko plemstvo." },
    royal_grand_fishing_net = { name = "Kraljevski veliki ribiška mreža", ropeCost = 4, goldCost = 2, silverCost = 2, linenCost = 2, threadCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 4600, food = 90, happiness = 12, prestige = 58, description = "Velika kraljevska ribiška mreža z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    net_workshop = { name = "Mrežna delavnica", cost = { gold = 260, wood = 120, stone = 120, rope = 6, thread = 6 }, upkeep = 6, qualityBonus = 5 },
    fishing_loft = { name = "Ribiška podstrešje", cost = { gold = 950, wood = 280, stone = 240, silver = 6, linen = 6 }, upkeep = 22, qualityBonus = 18 },
    master_net_atelier = { name = "Mojstrski mrežni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_fishery_palace = { name = "Kraljevska ribiška palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
FishingNetMaker.ropeStock = 16; FishingNetMaker.threadStock = 12; FishingNetMaker.linenStock = 12; FishingNetMaker.silverStock = 6; FishingNetMaker.goldStock = 6; FishingNetMaker.jewelStock = 4; FishingNetMaker.pearlStock = 4
FishingNetMaker.productStock = {}; FishingNetMaker.buildings = {}; FishingNetMaker.maker = nil; FishingNetMaker.activeMaking = {}; FishingNetMaker.totalProducts = 0; FishingNetMaker.dayTimer = 0
function FishingNetMaker.init() FishingNetMaker.ropeStock=16; FishingNetMaker.threadStock=12; FishingNetMaker.linenStock=12; FishingNetMaker.silverStock=6; FishingNetMaker.goldStock=6; FishingNetMaker.jewelStock=4; FishingNetMaker.pearlStock=4; FishingNetMaker.productStock={}; FishingNetMaker.buildings={}; FishingNetMaker.maker=nil; FishingNetMaker.activeMaking={}; FishingNetMaker.totalProducts=0; FishingNetMaker.dayTimer=0; print("[FishingNetMaker] Royal Fishing Net Maker System initialized (6 products, 4 buildings)") end
function FishingNetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FishingNetMaker.maker={name=n or ("Mrežar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mrežar najet: %s (spretnost: %d)",FishingNetMaker.maker.name,s),"success") end; return true end
function FishingNetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FishingNetMaker.build(id) local ok,e=FishingNetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FishingNetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FishingNetMaker.getQualityBonus() local b=0; for _,bd in ipairs(FishingNetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FishingNetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ropeCost and FishingNetMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.threadCost and FishingNetMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.linenCost and FishingNetMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.silverCost and FishingNetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FishingNetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FishingNetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FishingNetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FishingNetMaker.buildings==0 then return false,"Potrebna mrežna delavnica" end; if not FishingNetMaker.maker then return false,"Potreben mrežar" end; return true end
function FishingNetMaker.make(pt,qty) qty=qty or 1; local ok,e=FishingNetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ropeCost then FishingNetMaker.ropeStock=FishingNetMaker.ropeStock-d.ropeCost*qty end; if d.threadCost then FishingNetMaker.threadStock=FishingNetMaker.threadStock-d.threadCost*qty end; if d.linenCost then FishingNetMaker.linenStock=FishingNetMaker.linenStock-d.linenCost*qty end; if d.silverCost then FishingNetMaker.silverStock=FishingNetMaker.silverStock-d.silverCost*qty end; if d.goldCost then FishingNetMaker.goldStock=FishingNetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FishingNetMaker.jewelStock=FishingNetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FishingNetMaker.pearlStock=FishingNetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FishingNetMaker.maker then t=math.max(1,t-math.floor(FishingNetMaker.maker.skill/13)) end; table.insert(FishingNetMaker.activeMaking,{id="fishingnet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FishingNetMaker.completeMaking(m) local q=1.0+(FishingNetMaker.getQualityBonus()/100); if FishingNetMaker.maker then q=q+(FishingNetMaker.maker.skill/140) end; q=math.min(2.5,q); FishingNetMaker.productStock[m.productType]=(FishingNetMaker.productStock[m.productType] or 0)+m.quantity; FishingNetMaker.totalProducts=FishingNetMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FishingNetMaker.maker then FishingNetMaker.maker.itemsMade=FishingNetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FishingNetMaker.maker.skill=math.min(100,FishingNetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ribiška mreža izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fishingnet.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function FishingNetMaker.update(dt) if not _G.state then return end; FishingNetMaker.dayTimer=FishingNetMaker.dayTimer+dt; if FishingNetMaker.dayTimer>=30 then FishingNetMaker.dayTimer=0; for i=#FishingNetMaker.activeMaking,1,-1 do local m=FishingNetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FishingNetMaker.completeMaking(m); table.remove(FishingNetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FishingNetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FishingNetMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FishingNetMaker.getStats() return {ropeStock=FishingNetMaker.ropeStock,threadStock=FishingNetMaker.threadStock,linenStock=FishingNetMaker.linenStock,silverStock=FishingNetMaker.silverStock,goldStock=FishingNetMaker.goldStock,jewelStock=FishingNetMaker.jewelStock,pearlStock=FishingNetMaker.pearlStock,productStock=FishingNetMaker.productStock,numBuildings=#FishingNetMaker.buildings,hasMaker=FishingNetMaker.maker~=nil,makerName=FishingNetMaker.maker and FishingNetMaker.maker.name or "—",makerSkill=FishingNetMaker.maker and FishingNetMaker.maker.skill or 0,activeMaking=#FishingNetMaker.activeMaking,totalProducts=FishingNetMaker.totalProducts} end
return FishingNetMaker
